import{A as e}from"./chunks/AiCourseLab.d8737767.js";import{d as o,o as d,c as s,H as a,Q as t,_ as r}from"./chunks/framework.68eebb55.js";const l={class:"lesson"},p=t('<div class="meta" data-v-769170ae><span class="tag" data-v-769170ae>第 03 / 40 篇</span><span data-v-769170ae>第一阶段：AI 与大模型基础</span><span data-v-769170ae>阅读约 12–15 分钟</span></div><h1 data-v-769170ae>Transformer 与 Attention：ChatGPT 为什么能理解上下文？</h1><p data-v-769170ae>「吃苹果」和「苹果发布 iPhone」中的同一个词，为什么可以呈现不同语义？关键是 Transformer 的上下文计算。</p><h2 data-v-769170ae>一、为什么仅有 Embedding 还不够？</h2><p data-v-769170ae>相同 Token ID 通常对应相同的初始 Token Embedding，但经过 Transformer 后，会形成上下文相关的隐藏状态。</p><div class="visual" data-v-769170ae><div class="step" data-v-769170ae>苹果：相同初始 Embedding</div><div class="arrow" data-v-769170ae>↓ Self-Attention 与 Transformer</div><div class="cols" data-v-769170ae><div class="panel" data-v-769170ae>🍎 吃苹果：水果相关表示</div><div class="panel" data-v-769170ae>📱 苹果发布 iPhone：公司相关表示</div></div><p data-v-769170ae>注意：GPT 采用因果掩码，句首「苹果」不能直接关注后面的 iPhone；后续位置可以结合前文。</p></div><h2 data-v-769170ae>二、Self-Attention 是什么？</h2><p data-v-769170ae>Self-Attention 让当前位置根据 Query 与 Key 的匹配程度，对允许访问位置的 Value 进行加权聚合。</p><p data-v-769170ae>例如「小明把电脑放在桌子上，因为它太重了」，模型需要综合不同位置的信息来判断「它」的可能指代。</p>',9),c=t(`<p data-v-769170ae>注意力权重不是模型决策的完整解释。</p><h2 data-v-769170ae>三、Q、K、V</h2><table data-v-769170ae><thead data-v-769170ae><tr data-v-769170ae><th data-v-769170ae>名称</th><th data-v-769170ae>作用</th></tr></thead><tbody data-v-769170ae><tr data-v-769170ae><td data-v-769170ae>Query</td><td data-v-769170ae>我寻找什么信息？</td></tr><tr data-v-769170ae><td data-v-769170ae>Key</td><td data-v-769170ae>我有什么匹配特征？</td></tr><tr data-v-769170ae><td data-v-769170ae>Value</td><td data-v-769170ae>我能提供什么信息？</td></tr></tbody></table><div class="visual" data-v-769170ae><div class="step" data-v-769170ae>输入隐藏状态 X</div><div class="arrow" data-v-769170ae>↓ 可训练线性投影</div><div class="cols" data-v-769170ae><div class="panel" data-v-769170ae>Q = XW<sub data-v-769170ae>Q</sub></div><div class="panel" data-v-769170ae>K = XW<sub data-v-769170ae>K</sub></div></div><div class="step" data-v-769170ae>V = XW<sub data-v-769170ae>V</sub></div><div class="arrow" data-v-769170ae>↓</div><div class="step" data-v-769170ae>Attention：匹配并聚合信息</div></div><h2 data-v-769170ae>四、Attention 数学公式</h2><div class="formula" data-v-769170ae>Attention(Q,K,V) = softmax(QKᵀ / √dₖ) V</div><p data-v-769170ae>第一步计算 QKᵀ 匹配分数；第二步除以 √dₖ 缩放；第三步 Softmax 转为权重；第四步对 V 加权求和。</p><h3 data-v-769170ae>手算示例</h3><p data-v-769170ae>假设已缩放分数为 [1,2,3]，Softmax 约为 [0.09,0.245,0.665]。</p><pre data-v-769170ae><code data-v-769170ae>V1=[1,0], V2=[0,1], V3=[1,1]
0.09×V1 + 0.245×V2 + 0.665×V3
= [0.755, 0.910]</code></pre><p data-v-769170ae>这是无因果约束的教学示例；GPT 类模型首位置不能看到未来 Token。</p><h2 data-v-769170ae>五、Multi-Head Attention</h2><p data-v-769170ae>多个注意力头各自拥有投影参数，学习不同的关联模式。结果拼接后再经过线性投影。</p><div class="visual" data-v-769170ae><div class="step" data-v-769170ae>输入 X</div><div class="arrow" data-v-769170ae>↓</div><div class="cols" data-v-769170ae><div class="panel" data-v-769170ae>Head 1</div><div class="panel" data-v-769170ae>Head 2</div></div><div class="arrow" data-v-769170ae>↓</div><div class="step" data-v-769170ae>Concat + 输出投影</div></div><div class="formula" data-v-769170ae>MultiHead = Concat(head₁, …, headₕ) W<sub data-v-769170ae>O</sub></div><h2 data-v-769170ae>六、Causal Mask：为什么不能看到未来？</h2><p data-v-769170ae>GPT 类模型使用因果掩码：当前位置只能关注自身和之前的 Token。</p>`,17),h=t('<h2 data-v-769170ae>七、Transformer Block 还有什么？</h2><p data-v-769170ae>除了 Attention，还包含前馈网络、残差连接、归一化等结构，具体顺序随模型架构变化。</p><div class="visual" data-v-769170ae><div class="step" data-v-769170ae>输入隐藏状态</div><div class="arrow" data-v-769170ae>↓</div><div class="step" data-v-769170ae>Attention + 残差连接</div><div class="arrow" data-v-769170ae>↓</div><div class="step" data-v-769170ae>前馈网络 + 残差连接</div><div class="arrow" data-v-769170ae>↓</div><div class="step" data-v-769170ae>下一层隐藏状态</div></div><h2 data-v-769170ae>八、工程实践</h2><p data-v-769170ae>React + Node.js 聊天应用通常不需要手写 Attention。应用层重点是上下文管理、消息持久化、流式输出、RAG 和评估。</p><p data-v-769170ae><strong data-v-769170ae>Self-Attention 是模型内部机制，聊天历史管理是应用层职责。</strong></p><h2 data-v-769170ae>学习疑问与解答</h2><h3 data-v-769170ae>Q1：Self-Attention 是否根据上下文动态赋予每个 Token 语义？</h3><p data-v-769170ae>提问日期：2026-10-15</p><p data-v-769170ae><strong data-v-769170ae>更准确地说，Self-Attention 动态聚合上下文信息并更新 Token 的向量表示，而不是直接分配语义标签。</strong></p><p data-v-769170ae>同一个 Token 的初始 Embedding 可以相同，但多层 Transformer 计算后隐藏状态不同。GPT 的因果掩码还限制了当前位置能够访问的上下文。</p><p data-v-769170ae>复习要点：动态更新的是表示，不是直接给 Token 打标签。</p><h2 data-v-769170ae>复习题</h2><ol data-v-769170ae><li data-v-769170ae>同一个 Token 为什么会形成不同的上下文表示？</li><li data-v-769170ae>Q、K、V 分别做什么？</li><li data-v-769170ae>Softmax 权重有什么特点？</li><li data-v-769170ae>GPT 为什么需要因果掩码？</li><li data-v-769170ae>Attention 与应用层聊天记忆有什么区别？</li></ol><footer data-v-769170ae><a href="./02-token-and-embedding" data-v-769170ae>← 上一篇</a><span data-v-769170ae>第 03 篇</span></footer>',15),_=o({__name:"TransformerLesson",setup(v){return(i,n)=>(d(),s("article",l,[p,a(e,{type:"attention"}),c,a(e,{type:"mask"}),h]))}});const m=r(_,[["__scopeId","data-v-769170ae"]]),b=JSON.parse('{"title":"03 · Transformer 与 Attention：ChatGPT 为什么能理解上下文？","description":"","frontmatter":{"title":"03 · Transformer 与 Attention：ChatGPT 为什么能理解上下文？","outline":"deep"},"headers":[],"relativePath":"guide/ai/chatbot-course/03-transformer-attention.md","filePath":"guide/ai/chatbot-course/03-transformer-attention.md","lastUpdated":1792049004000}'),u={name:"guide/ai/chatbot-course/03-transformer-attention.md"},A=Object.assign(u,{setup(v){return(i,n)=>(d(),s("div",null,[a(m)]))}});export{b as __pageData,A as default};
